51	
52	    private final ServerSocket serverSocket;
53	    private final CopyOnWriteArrayList<ClientConnection> connections = new CopyOnWriteArrayList<>();
54	    private final String hubName;
55	
56	    /**
57	     * Creates a hub bound to the given port.
58	     * Use {@code port = 0} to let the OS assign an ephemeral port; read the
59	     * actual port back via {@link #port()}.
60	     *
61	     * @param port the TCP port to bind; 0 for ephemeral
62	     * @throws IOException if the server socket cannot be created
63	     */
64	    public CrossProcessTaskHub(int port) throws IOException {
65	        this.hubName = String.valueOf(HUB_COUNTER.getAndIncrement());
66	        this.serverSocket = new ServerSocket(port);
67	        startAcceptLoop();
68	    }
